    responseText = getDataOut.success.body;
}

// 3. Initialize the result object
let aiResult = {};

// 4. Safely parse the Server-Sent Events (SSE) string
if (typeof responseText === 'string') {
    let lines = responseText.split(/\r?\n/);

    for (let i = 0; i < lines.length; i++) {
        let currentLine = lines[i].trim();

        // Scenario A: AI completed successfully
        if (currentLine.startsWith('event: complete')) {
            let dataLine = lines[i + 1];
            if (dataLine && dataLine.trim().startsWith('data: ')) {
                let jsonString = dataLine.replace('data: ', '').trim();
                try {
                    let parsedArray = JSON.parse(jsonString);
                    aiResult = parsedArray[0]; 
                } catch (e) {
                    aiResult = { status: "Error parsing AI data", risk_code: -1 };
                }
            }
            break; 
        }

        // Scenario B: Hugging Face threw an error (like ZeroGPU quota)
        else if (currentLine.startsWith('event: error')) {
            let dataLine = lines[i + 1];
            if (dataLine && dataLine.trim().startsWith('data: ')) {
                let jsonString = dataLine.replace('data: ', '').trim();
                try {
                    let errorData = JSON.parse(jsonString);
                    aiResult = { 
                        status: "API Quota Exceeded", 
                        risk_code: -1,
                        details: errorData.error 
                    };
                } catch (e) {
                    aiResult = { status: "Unknown Hugging Face Error", risk_code: -1 };
                }
            }
            break;
        }
    }
}

